    "content": "29/08/2026 - 22:59 联合国气候事务负责人西蒙·斯蒂尔和尼泊尔外交部长希希尔·卡纳尔周六（8月29日）警告，气候变化正日益威胁喜马拉雅地区。尼泊尔与中国西藏交界地区日前发生冰川崩塌，引发致命洪水和泥石流，造成的死亡人数升至682人、约3000人失踪。卡纳尔呼吁：国际社会团结起来，共同保护喜马拉雅生态系统。尼泊尔称，灾区重建费用预计将达到“数十亿美元”。 根据官方初步统计，自26日洪灾发生以来，救援人员已从厚重泥浆以及被洪水摧毁的建筑、道路、桥梁和施工现场废墟中挖出682具遗体，其中尼泊尔一侧675具…"
