    "content": "新华社耶路撒冷8月29日电（记者陈君清 冯国芮）以色列第12频道电视台29日以以色列国家安全总局（辛贝特）为信源报道说，该部门特工曾紧急将以总理内塔尼亚胡的长子亚伊尔“从美国迈阿密救回以色列”。 报道称，辛贝特经评估认为，亚伊尔当时“面临重大安全威胁”，于是实施紧急营救将其送回以色列。不过，辛贝特并未具体说明威胁细节。 报道还说，辛贝特将部分特工从当时身处美国纽约的以总统赫尔佐格身边调往迈阿密，以便执行该行动。 内塔尼亚胡有两个儿子，亚伊尔和阿夫纳。阿夫纳长期生活在以色列，而亚伊尔曾长期居住在迈阿密，是其父亲的重要…"
