    "description": "新华社天津8月29日电（记者张泽伟、韦骅）中国女排29日在2026年女排亚锦赛半决赛中3:0战胜伊朗队，将在决赛中对阵泰国队。中国女排主教练赵勇说，决赛中要坚定信心、全力以赴去拼。 对于中国队与伊朗队这场半决赛，赵勇点评说：“我们赛前做了充分准备。从结果来看，整体技术发挥尚可。” 虽然中国队在小组赛阶段以3:0战胜过伊朗队，但半决赛再相遇，首局并不顺利，比分一度落后。对此，赵勇表示：“伊朗队是历史性首进亚锦赛四强，冲劲非常足，防守也非常…",
    "content": "新华社天津8月29日电（记者张泽伟、韦骅）中国女排29日在2026年女排亚锦赛半决赛中3:0战胜伊朗队，将在决赛中对阵泰国队。中国女排主教练赵勇说，决赛中要坚定信心、全力以赴去拼。 对于中国队与伊朗队这场半决赛，赵勇点评说：“我们赛前做了充分准备。从结果来看，整体技术发挥尚可。” 虽然中国队在小组赛阶段以3:0战胜过伊朗队，但半决赛再相遇，首局并不顺利，比分一度落后。对此，赵勇表示：“伊朗队是历史性首进亚锦赛四强，冲劲非常足，防守也非常顽强，给我们留下了很深的印象。我们首局遇到困难，但我告诉队员，要对自己、对队友坚…"
