    "content": "新华社西藏吉隆8月29日电 特写：温情吉隆镇 新华社记者杨守勇、格桑边觉、李键 吉隆，一个地处中尼交界的边境小镇，这几天承载着万千牵挂。来自祖国各地的救援物资和各类装备汇集这里，各方救援力量也在这里集结。 早上9时，来自甘肃的货车司机马给布夫妻俩吃完早餐，准备回家。“我拉过来的铲车已经交付，应该能到达救援现场了。”从林芝米林市赶到吉隆镇，马给布夫妇开车近30个小时，“稍微休息休息，我们就往回撤，不给地方添麻烦。” 行走不远，记者看到一名马姓货车司机正在驾驶室休息。随车的工人说，他们送来的这一车物资，是一线急需的十几…"
