    "content": "新华社济南8月29日电（记者王志、顾天成）29日，第十一届非洲职业技能挑战赛（ATC）在山东潍坊职业学院开赛，来自喀麦隆、加纳、卢旺达、塞内加尔、南非、津巴布韦6个非洲国家的68名参赛选手同台竞技、角逐奖项。 “比赛不仅帮助我和同伴们拓展专业技能，也为我们搭建起在国际舞台展现自我风采的宝贵平台。”加纳参赛选手如森说，他希望把在中国学到的本领运用到未来工作当中，投身航空维修、无人机运输等相关领域。 据了解，非洲职业技能挑战赛是一项海外公益项目，由中国航空工业集团有限公司旗下的中航科创有限公司主办，采用“线上前置培训+…"
