    "content": "新华社昆明8月29日电（记者赵珮然、严勇）8月28日下午至29日上午，云南省西双版纳傣族自治州勐腊县普降大到暴雨，昆明市托管的勐腊县磨憨镇24小时最大降雨量187.5毫米，导致磨憨镇发生洪涝灾害。 据昆明市防汛抗旱指挥部办公室29日20时10分发布通报，磨憨镇磨龙村盐塘水库出现漫坝险情，存在溃坝风险。险情发生后，昆明市已启动防汛重大级（Ⅱ级）应急响应，立即组织应急力量开展抢险避险工作，对危险区域群众进行紧急转移安置。截至8月29日16时，已经转移磨龙、尚勇、尚冈、曼庄等6个村（社区）2200余人，根据现场情况科学研…"
