    "content": "我的咖啡装备进化史 咖啡机一路从最初的 摩卡壶 ，到 V60 手冲 ，再到 飞利浦 5 系全自动咖啡机 ，最后折腾到了现在的 Flair 58+2 手压咖啡机 。 磨豆机也是一路升级：最开始直接买磨好的咖啡粉，后来入了 汉匠 K6 手磨 ，再到现在的 咖锐客 DF64V3 电磨 。 目前这套 Flair 58+2 + DF64V3 ，对我来说已经是家用意式里非常有可玩性的一套组合了。 手压虽然比半自动多了一点操作，但可以自己控制 预浸、压力和流速 ，整个萃取过程参与感很强，确实挺有意思。"
