    "title": "亚马逊上线竞价机制，第三方卖家可付费提速“数小时达”服务",
    "link": "https://www.ithome.com/0/996/025.htm",
    "pub_date": "2026-08-29 20:06:25",
    "author": "",
    "description": "IT之家 8 月 29 日消息，据《商业内幕》今天（29 日）报道，亚马逊开始借助第三方卖家扩大旗下的数小时送达服务，同时准备让部分卖家为获得这种配送速度额外付费。 本月早些时候，亚马逊向部分使用亚马逊物流（FBA）的卖家发出邮件，要求卖家自行报价，争取让旗下商品进入“数小时达（Sub-Same Day）”配送范围。 亚马逊称，数小时达最快能在下单后 2 小时送到消费者手中，目前覆盖 2300 个都市圈。使用该服务的商品平均销量比普通 …",
    "content": "IT之家 8 月 29 日消息，据《商业内幕》今天（29 日）报道，亚马逊开始借助第三方卖家扩大旗下的数小时送达服务，同时准备让部分卖家为获得这种配送速度 额外付费 。 本月早些时候，亚马逊向部分使用亚马逊物流（FBA）的卖家发出邮件，要求卖家自行报价，争取让旗下商品进入“数小时达（Sub-Same Day）”配送范围。 亚马逊称，数小时达最快能在 下单后 2 小时 送到消费者手中，目前覆盖 2300 个都市圈。使用该服务的商品平均销量比普通 FBA 配送商品高 12%。“只有商品实际通过数小时达发货时，才会按照你…"
