    "content": "29/08/2026 - 13:38 冰岛8月29日举行公民投票，确定是否重启与欧盟中断13年的入盟谈判。尽管欧盟乐见接纳这个富裕而且稳定的国家为新成员，但冰岛居民对作为该国经济支柱的渔业是否会在加入欧盟后受到限制的担心，使得这次公投结果胜负难料。 这个有着40万居民的北欧岛国原本2009年就提出入盟申请，当时，席卷全球的金融风暴重创岛国经济。但是，与布鲁塞尔的入盟谈判2010年启动之后，因新上台的执政联盟不看好欧盟，而于2013年被叫停。 如今国际地缘政治格局大变，不仅欧洲联盟正努力向其它地区开放合作关系，与印度…"
