    "description": "新华社雷克雅未克8月29日电（记者朱昊晨 张兆卿）冰岛29日举行全民公投，就是否重启加入欧盟的谈判进行表决。 冰岛人口约40万。此次公投于当地时间29日9时开始。选民只需选择“赞成”或“反对”。投下“赞成”票意味着同意授权政府重启入盟谈判。计票将在当天22时投票结束后开始。 冰岛2009年申请加入欧盟并启动相关谈判。2013年，持疑欧立场的政府上台后搁置谈判。 有分析认为，如果冰岛最终加入欧盟，可能对欧洲的其他非欧盟国家产生示范效应。",
    "content": "新华社雷克雅未克8月29日电（记者朱昊晨 张兆卿）冰岛29日举行全民公投，就是否重启加入欧盟的谈判进行表决。 冰岛人口约40万。此次公投于当地时间29日9时开始。选民只需选择“赞成”或“反对”。投下“赞成”票意味着同意授权政府重启入盟谈判。计票将在当天22时投票结束后开始。 冰岛2009年申请加入欧盟并启动相关谈判。2013年，持疑欧立场的政府上台后搁置谈判。 有分析认为，如果冰岛最终加入欧盟，可能对欧洲的其他非欧盟国家产生示范效应。"
