    "content": "应埃及总统塞西邀请，国家主席习近平即将对埃及进行国事访问。习近平主席时隔10年再次对埃及进行国事访问，适逢中埃建交70周年，对两国关系发展具有承前启后、继往开来的特殊重要意义。 作为世界两大文明古国，中埃友好交往跨越千年、薪火相传。早在两千多年前，古丝绸之路便搭建起两大文明交流互鉴的桥梁，开启了文明对话的古老篇章。 1956年，埃及在阿拉伯和非洲国家中率先同新中国建交。70年来，无论国际和地区形势如何变化，两国始终相互尊重、平等相待、彼此信任、守望相助，中埃关系已经成为发展中国家友好相处、团结协作的典范和中阿、中非…"
